@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or keyword…" />
    </div>
    <div class="col-md-4">
        <label for="department" class="form-label">Department</label>
        <select id="department" name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id" selected="@(dept.Id == Department)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses match your criteria. Try adjusting the filters above.</div>
}
else
{
    <p class="text-muted">Showing @_courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in _courses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td>@course.Title</td>
                        <td>@(_departmentNames.GetValueOrDefault(course.DepartmentId, course.DepartmentId))</td>
                        <td>@course.Credits</td>
                        <td>@course.Instructor.Name</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private IReadOnlyList<Department> _departments = [];
    private Dictionary<string, string> _departmentNames = new();

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _departmentNames = _departments.ToDictionary(d => d.Id, d => d.Name);
        _courses = Catalog.GetCourses(Department, Search);
    }
}

@page "/courses/{CourseId}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService Catalog

@if (_course is null)
{
    <PageTitle>Course Not Found — University Course Catalog</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found. <a href="/courses">Browse all courses</a>.</p>
}
else
{
    <PageTitle>@_course.Code @_course.Title — University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="/courses?department=@_course.DepartmentId">@(_departmentName ?? _course.DepartmentId)</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <h1>@_course.Code — @_course.Title</h1>

    <div class="row mt-4">
        <div class="col-lg-8">
            <h2 class="h5">Description</h2>
            <p>@_course.Description</p>

            <h2 class="h5 mt-4">Schedule &amp; Location</h2>
            <ul class="list-unstyled">
                <li><strong>Schedule:</strong> @_course.Schedule</li>
                <li><strong>Room:</strong> @_course.Room</li>
                <li><strong>Credits:</strong> @_course.Credits</li>
            </ul>
        </div>

        <div class="col-lg-4">
            <div class="card">
                <div class="card-body">
                    <h2 class="h5 card-title">Instructor</h2>
                    <p class="mb-1"><strong>@_course.Instructor.Name</strong></p>
                    <p class="text-muted mb-2">@_course.Instructor.Title</p>
                    <p class="small">@_course.Instructor.Bio</p>
                    <p class="mb-0"><a href="mailto:@_course.Instructor.Email">@_course.Instructor.Email</a></p>
                </div>
            </div>

            <a href="/enroll?courseId=@_course.Id" class="btn btn-primary w-100 mt-3">Request Enrollment</a>
        </div>
    </div>
}

@code {
    [Parameter] public string CourseId { get; set; } = "";

    private Course? _course;
    private string? _departmentName;

    protected override void OnInitialized()
    {
        _course = Catalog.GetCourse(CourseId);
        if (_course is not null)
        {
            _departmentName = Catalog.GetDepartment(_course.DepartmentId)?.Name;
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted</h4>
        <p>Thank you, <strong>@_model.FullName</strong>. Your enrollment request for
            <strong>@(_selectedCourseTitle ?? _model.CourseId)</strong> has been received.</p>
        <hr />
        <p class="mb-0"><a href="/courses">Browse more courses</a> or <a href="/enroll">submit another request</a>.</p>
    </div>
}
else
{
    <p>Fill out the form below to request enrollment in a course. All fields are required.</p>

    <EditForm method="post" Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="needs-validation">
        <AntiforgeryToken />
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger mb-3" />

        <div class="mb-3">
            <label for="fullName" class="form-label">Full Name</label>
            <InputText id="fullName" @bind-Value="_model.FullName" class="form-control" />
            <ValidationMessage For="() => _model.FullName" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" @bind-Value="_model.StudentId" class="form-control" placeholder="e.g. STU-12345" />
            <ValidationMessage For="() => _model.StudentId" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" @bind-Value="_model.CourseId" class="form-select">
                <option value="">— Select a course —</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id">@course.Code — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.CourseId" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();
    [SupplyParameterFromQuery] public string? CourseId { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private bool _submitted;
    private string? _selectedCourseTitle;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        // Pre-select the course if provided via query string and the form hasn't been posted yet
        if (!_submitted && string.IsNullOrEmpty(_model.CourseId) && !string.IsNullOrEmpty(CourseId))
        {
            _model.CourseId = CourseId;
        }
    }

    private void HandleSubmit()
    {
        _selectedCourseTitle = _courses
            .FirstOrDefault(c => c.Id == _model.CourseId)
            ?.let(c => $"{c.Code} — {c.Title}");

        Catalog.SubmitEnrollmentRequest(_model);
        _submitted = true;
    }
